 denied:=false;begin perform public.save_property_bookkeeping(companies[1],deals[1],entries[1],'{"reconciled":"true"}');exception when invalid_parameter_value then denied:=true;end;
 if not denied then raise exception 'Non-boolean reconciliation accepted';end if;
